// Runtime adapter for code generated by the Flick compiler. Generated code
// imports only this package; Effect stays behind it (§11 "Runtime adapter").
//
// shortcut: entry runner and Platform calls for the bootstrap codegen only,
// replaced by the full owner/scope runner and stdlib adapters in M8/M9.
import { Cause, Effect, Exit } from "effect";

const writeLine = (stream, text) => Effect.sync(() => void stream.write(`${text}\n`));

export const stdoutLine = (text) => writeLine(process.stdout, text);

export const stderrLine = (text) => writeLine(process.stderr, text);

/** `App.fail`: the stdlib `AppError` as a typed failure. */
export const appFail = (message) => Effect.fail({ _tag: "AppError", message });

/** Runs effects left to right; the result is `Unit`. */
export const seq = (effects) => Effect.asVoid(Effect.forEach(effects, (effect) => effect));

/**
 * Runs `main : Unit ->{none; AppError} Unit` and sets the process exit code:
 * 0 on success, 1 on a typed `AppError` (its message goes to stderr) or any
 * other failure (the Cause is printed).
 */
export const runMain = async (main) => {
  const exit = await Effect.runPromiseExit(main());
  if (Exit.isSuccess(exit)) {
    process.exitCode = 0;
    return;
  }
  const appError = exit.cause.reasons.find(
    (reason) => Cause.isFailReason(reason) && reason.error?._tag === "AppError",
  );
  process.stderr.write(
    appError ? `error: ${appError.error.message}\n` : `${Cause.pretty(exit.cause)}\n`,
  );
  process.exitCode = 1;
};
